		name    string
		origins string
		wantErr bool
	}{
		{name: "omitted"},
		{name: "empty list", origins: "[]"},
		{name: "public and private HTTPS origins", origins: "[https://auth.example.invalid, 'https://[::1]:8443/', https://10.0.0.2]"},
		{name: "plaintext", origins: "[http://auth.example.invalid]", wantErr: true},
