			if tc.origins != "" {
				data += "harpoon:\n  oauth_forward_origins: " + tc.origins + "\n"
			}
			for name, validate := range map[string]func(string, []byte) error{
				"runtime": ValidateProfileBytes,
				"full":    ValidateFullProfileBytes,
			} {
